<template>
  <q-page class="q-pa-lg">
    <div class="row items-center justify-between q-mb-md">
      <div>
        <div class="text-h5 text-weight-bold">
          <q-icon name="security" color="primary" class="q-mr-sm" />
          Giám Sát Bảo Mật & Phiên Đăng Nhập
        </div>
        <div class="text-caption text-grey-6">
          Theo dõi máy đang online theo IP/User-Agent, gỡ khóa brute-force và xem lịch sử đăng nhập
        </div>
      </div>
      <q-btn outline color="primary" icon="refresh" label="Làm mới" @click="loadAll" />
    </div>

    <div class="row q-col-gutter-lg">
      <!-- Active Sessions & Lockouts -->
      <div class="col-12 col-xl-7">
        <!-- Active Sessions -->
        <q-card class="q-mb-lg">
          <q-card-section class="row items-center justify-between">
            <div class="text-subtitle1 text-weight-bold text-primary">
              <q-icon name="wifi_tethering" class="q-mr-sm text-positive" />
              Các Thiết Bị Đang Truy Cập (Live Active Sessions)
            </div>
            <q-badge color="cyan-9" :label="sessions.length + ' máy online'" />
          </q-card-section>
          <q-separator />
          <q-table
            :rows="sessions"
            :columns="sessionColumns"
            row-key="session_key"
            flat
            :pagination="{ rowsPerPage: 5 }"
            no-data-label="Chưa có phiên nào hoạt động"
          >
            <template #body-cell-client_ip="props">
              <q-td :props="props">
                <q-badge color="cyan-10" text-color="white" class="text-weight-bold q-pa-xs">
                  <q-icon name="laptop" class="q-mr-xs" />
                  {{ props.row.client_ip }}
                </q-badge>
              </q-td>
            </template>

            <template #body-cell-user_agent="props">
              <q-td :props="props">
                <span class="text-caption text-grey-7" style="max-width: 250px; display: inline-block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;" :title="props.row.user_agent">
                  {{ props.row.user_agent }}
                </span>
              </q-td>
            </template>

            <template #body-cell-actions="props">
              <q-td :props="props">
                <q-btn outline dense color="negative" icon="block" label="Đăng xuất từ xa" @click="revokeSession(props.row)" />
              </q-td>
            </template>
          </q-table>
        </q-card>

        <!-- Lockouts Manager -->
        <q-card>
          <q-card-section class="row items-center justify-between">
            <div class="text-subtitle1 text-weight-bold text-amber-9">
              <q-icon name="lock_person" class="q-mr-sm" />
              Danh Sách IP Bị Khóa Tạm Thời (Brute-Force Lockout)
            </div>
            <q-badge color="amber-9" :label="lockouts.length + ' mục bị khóa'" />
          </q-card-section>
          <q-separator />
          <q-card-section>
            <div v-if="lockouts.length === 0" class="text-center q-pa-md text-grey-6">
              <q-icon name="verified" size="32px" color="positive" class="q-mb-xs" />
              <div>Hiện không có địa chỉ IP hay tài khoản nào bị khóa. Hệ thống an toàn!</div>
            </div>
            <div v-else class="q-gutter-sm">
              <div v-for="item in lockouts" :key="item.target" class="row items-center justify-between q-pa-sm bg-grey-2 rounded-borders">
                <div>
                  <span class="text-weight-bold text-amber-9">{{ item.target }}</span>
                  <span class="text-caption text-grey-7 q-ml-sm">Sai {{ item.failed_attempts }} lần | Khóa còn: {{ item.remaining_seconds }}s</span>
                </div>
                <q-btn unelevated dense color="positive" icon="lock_open" label="Gỡ khóa ngay" @click="unblockTarget(item.target)" />
              </div>
            </div>
          </q-card-section>
        </q-card>
      </div>

      <!-- Access Audit Logs -->
      <div class="col-12 col-xl-5">
        <q-card>
          <q-card-section class="row items-center justify-between">
            <div class="text-subtitle1 text-weight-bold text-primary">
              <q-icon name="history" class="q-mr-sm" />
              Nhật Ký Truy Cập (Security Audit Log)
            </div>
            <div class="text-caption text-grey-6">50 lần gần nhất</div>
          </q-card-section>
          <q-separator />
          <q-table
            :rows="auditLogs"
            :columns="auditColumns"
            row-key="id"
            flat
            :pagination="{ rowsPerPage: 10 }"
            no-data-label="Chưa có nhật ký"
          >
            <template #body-cell-status="props">
              <q-td :props="props">
                <q-badge :color="props.row.status === 'success' ? 'positive' : (props.row.status === 'failed_password' ? 'negative' : 'warning')">
                  {{ props.row.status === 'success' ? 'Thành công' : (props.row.status === 'failed_password' ? 'Sai Pass' : 'Bị Khóa') }}
                </q-badge>
              </q-td>
            </template>
          </q-table>
        </q-card>
      </div>
    </div>
  </q-page>
</template>

<script>
import { defineComponent, ref, onMounted } from 'vue'
import { useQuasar } from 'quasar'

export default defineComponent({
  name: 'SecurityAudit',
  setup () {
    const $q = useQuasar()
    const sessions = ref([])
    const lockouts = ref([])
    const auditLogs = ref([])

    const sessionColumns = [
      { name: 'client_ip', label: 'Địa chỉ IP', field: 'client_ip', sortable: true, align: 'left' },
      { name: 'username', label: 'Tài khoản', field: 'username', sortable: true, align: 'left' },
      { name: 'role', label: 'Vai trò', field: 'role', sortable: true, align: 'center' },
      { name: 'user_agent', label: 'Thiết bị / Trình duyệt', field: 'user_agent', align: 'left' },
      { name: 'last_active', label: 'Hoạt động gần nhất', field: 'last_active', sortable: true, align: 'left' },
      { name: 'actions', label: 'Thao tác', align: 'center' }
    ]

    const auditColumns = [
      { name: 'timestamp', label: 'Thời gian', field: 'timestamp', sortable: true, align: 'left' },
      { name: 'username', label: 'Tài khoản', field: 'username', sortable: true, align: 'left' },
      { name: 'ip_address', label: 'Địa chỉ IP', field: 'ip_address', sortable: true, align: 'left' },
      { name: 'status', label: 'Kết quả', field: 'status', align: 'center' }
    ]

    const loadAll = async () => {
      try {
        const [sessRes, lockRes, auditRes] = await Promise.all([
          fetch('/api/admin/security/active-sessions').then(r => r.json()),
          fetch('/api/admin/security/lockouts').then(r => r.json()),
          fetch('/api/admin/security/audit-logs?limit=50').then(r => r.json())
        ])
        sessions.value = sessRes.sessions || []
        lockouts.value = lockRes.lockouts || []
        auditLogs.value = auditRes.logs || []
      } catch (err) {
        $q.notify({ type: 'negative', message: 'Lỗi tải dữ liệu bảo mật' })
      }
    }

    const revokeSession = (row) => {
      $q.dialog({
        title: 'Hủy phiên làm việc',
        message: `Đăng xuất từ xa IP ${row.client_ip} (${row.username})?`,
        cancel: true,
        persistent: true,
        ok: { label: 'Đăng xuất', color: 'negative' }
      }).onOk(async () => {
        try {
          const res = await fetch('/api/admin/security/revoke-session', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ session_key: row.session_key })
          })
          const data = await res.json()
          $q.notify({ type: 'positive', message: data.message || 'Đã hủy phiên' })
          await loadAll()
        } catch (err) {
          $q.notify({ type: 'negative', message: err.message })
        }
      })
    }

    const unblockTarget = async (target) => {
      try {
        const res = await fetch('/api/admin/security/unblock', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ target })
        })
        const data = await res.json()
        $q.notify({ type: 'positive', message: data.message })
        await loadAll()
      } catch (err) {
        $q.notify({ type: 'negative', message: err.message })
      }
    }

    onMounted(loadAll)

    return {
      sessions,
      lockouts,
      auditLogs,
      sessionColumns,
      auditColumns,
      loadAll,
      revokeSession,
      unblockTarget
    }
  }
})
</script>
